#!/usr/bin/env bash\nset -e\n# Build the Docker image\ndocker build -t nightly-quote-mixer-test . > /dev/null\n# Run container with deterministic indices\nOUTPUT=$(docker run --rm -e QUOTE1_IDX=0 -e QUOTE2_IDX=0 nightly-quote-mixer-test)\nEXPECTED="The early bird catches the worm. Even the darkest night ends."\nif [ "$OUTPUT" = "$EXPECTED" ]; then\n  echo "PASS"\n  exit 0\nelse\n  echo "FAIL: got '$OUTPUT'"\n  exit 1\nfi
